const DEFAULT_IN_VIEW_THRESHOLD = 0.9;

export function getDataValue(node, key, fallback) {
    const value = node.dataset[key];

    if (value === undefined) {
        return fallback;
    }

    if (value === 'true') {
        return true;
    }

    if (value === 'false') {
        return false;
    }

    if (value.trim() !== '' && !Number.isNaN(Number(value))) {
        return Number(value);
    }

    return value;
}

export function getCarouselOptions(emblaNode) {
    return {
        slidesToScroll: getDataValue(emblaNode, 'slidesToScroll', 1),

        align: getDataValue(emblaNode, 'align', 'start'),

        loop: getDataValue(emblaNode, 'loop', false),

        inViewThreshold: getDataValue(
            emblaNode,
            'inViewThreshold',
            DEFAULT_IN_VIEW_THRESHOLD
        ),
    };
}
